create policy "Enable select for users based on user_id"
on "public"."contract_addendums"
as permissive
for select
to public
using ((auth.uid() = user_id));


create policy "Enable update for extractors based on email"
on "public"."contract_addendums"
as permissive
for update
to public
using ((((auth.jwt() ->> 'email'::text) = 'ext_1@postsig.com'::text) OR ((auth.jwt() ->> 'email'::text) = 'extraction@postsig.com'::text)))
with check ((((auth.jwt() ->> 'email'::text) = 'ext_1@postsig.com'::text) OR ((auth.jwt() ->> 'email'::text) = 'extraction@postsig.com'::text)));


create policy "Enable users to update their own contracts"
on "public"."contract_addendums"
as permissive
for update
to public
using ((auth.uid() = user_id))
with check ((auth.uid() = user_id));


create policy "Give full access to extractors"
on "public"."contract_addendums"
as permissive
for select
to authenticated
using ((((auth.jwt() ->> 'email'::text) = 'ext_1@postsig.com'::text) OR ((auth.jwt() ->> 'email'::text) = 'extraction@postsig.com'::text)));


create policy "Users can insert into contracts"
on "public"."contract_addendums"
as permissive
for insert
to authenticated
with check (true);


create policy "Users can view their own contracts"
on "public"."contract_addendums"
as permissive
for select
to public
using ((auth.uid() = user_id));


